import heapq


def _round(n, mode):
    if mode == "half_up":
        return (n + 5000) // 10000
    return n // 10000


def _ledger(data, sequence_first, discounted, refund):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            rank = (seq, event.get("revision", 0), pos)
        else:
            rank = (event.get("revision", 0), pos)
        if event_id not in winners or rank > winners[event_id][0]:
            winners[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        amount = net + tax
        if refund and event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolve(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        options.append([None] + versions)

    best = None
    best_vector = None
    for choice in product(*options):
        selected = {name: version for name, version in zip(names, choice)
                    if version is not None}
        constraints = {}
        graph = {}
        pending = []
        for name, bounds in data["roots"].items():
            pending.append((name, bounds[0], bounds[1]))
        reached = set()
        valid = True
        while pending:
            name, low, high = pending.pop()
            constraints.setdefault(name, []).append((low, high))
            if name not in selected:
                valid = False
                break
            if name in reached:
                continue
            reached.add(name)
            row = next(row for row in packages[name]
                       if row["version"] == selected[name])
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                deps.append(dep["name"])
                pending.append((dep["name"], dep["min"], dep["max"]))
            graph[name] = deps
        if not valid or reached != set(selected):
            continue
        if any(not all(low <= selected[name] <= high for low, high in ranges)
               for name, ranges in constraints.items()):
            continue

        state = {}
        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not acyclic(dep) for dep in graph.get(name, [])):
                return False
            state[name] = 2
            return True
        if not all(acyclic(name) for name in reached):
            continue

        vector = tuple(selected.get(name, -1) for name in names)
        if best_vector is None or vector < best_vector:
            best, best_vector = selected, vector
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_ids = None
    best_value = None
    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        candidate_ids = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and candidate_ids < best_ids)):
            best_value, best_ids = value, candidate_ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source, target = data["source"], data["target"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    dist = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == target and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(depart + edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((depart + duration, remaining - 1))
            next_node = edge["v"]
            next_mask = mask | bit.get(next_node, 0)
            for arrival, left in choices:
                if arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


